-- 0053_transfer_requests (ADR-0116): a transfer request as a header of groups — one transfers row per
-- source warehouse — with the destination's count (COUNTED) before the source's confirmation, counted
-- quantities and unrequested lines. Generated by `pnpm db:generate --name=transfer_requests` (drizzle
-- numbered it 0052 after the gap at 0039; renamed with its snapshot), then the tail by hand: every
-- existing request gets its header, and the header is never deleted (ADR-0035). Applied migrations are
-- never edited.

CREATE TABLE "transfer_requests" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "transfer_requests_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"dest_warehouse_id" bigint NOT NULL,
	"status" text DEFAULT 'DRAFT' NOT NULL,
	"note" text,
	"requested_at" timestamp with time zone,
	"requested_by" bigint,
	"created_by" bigint,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "transfer_requests_status" CHECK ("transfer_requests"."status" IN ('DRAFT', 'REQUESTED', 'SHIPPED', 'COUNTED', 'RECEIVED', 'CANCELLED')),
	CONSTRAINT "transfer_requests_note" CHECK ("transfer_requests"."note" IS NULL OR length("transfer_requests"."note") BETWEEN 1 AND 500)
);
