-- Hand-written (ADR-0116): every REQUEST transfer made before this migration becomes a one-group request.
DO $$
DECLARE
  t RECORD;
  rid bigint;
BEGIN
  FOR t IN SELECT * FROM transfers WHERE origin = 'REQUEST' AND request_id IS NULL ORDER BY id LOOP
    INSERT INTO transfer_requests (dest_warehouse_id, status, note, requested_at, requested_by, created_by, created_at, updated_at)
    VALUES (t.dest_warehouse_id, t.status, t.note, t.requested_at, t.requested_by, t.created_by, t.created_at, t.updated_at)
    RETURNING id INTO rid;
    UPDATE transfers SET request_id = rid WHERE id = t.id;
  END LOOP;
END $$;--> statement-breakpoint
